 void AddReminderPointPicker(Panel body,TextBox values){var controls=Row(body);Label(controls,"添加提前分钟");var picker=new ComboBox{Width=100,IsEditable=true,Text="10",Margin=new Thickness(0,4,8,4)};foreach(int n in new[]{0,1,2,3,5,10,15,20,30,45,60,90,120})picker.Items.Add(n.ToString());SetAccessibleName(picker,"提醒点分钟选择");controls.Children.Add(picker);Button(controls,"＋添加提醒点",()=>values.Text=String.Join(",",ReminderPoints.Parse(values.Text+","+picker.Text)));Button(controls,"清空提醒点",()=>values.Text="");var chips=new WrapPanel{Margin=new Thickness(0,4,0,8)};body.Children.Add(chips);Action render=()=>{chips.Children.Clear();try{var points=ReminderPoints.Parse(values.Text);foreach(int n in points){int minute=n;AddButton(chips,(minute==0?"到点":minute+"分钟前")+" ×",()=>values.Text=String.Join(",",ReminderPoints.Parse(values.Text).Where(x=>x!=minute)));}}catch(ArgumentException){}};values.TextChanged+=(s,e)=>render();render();}
 static int ReadWorkEndTime(ComboBox hour,ComboBox minute){int h,m;if(!Int32.TryParse(hour.Text,out h)||h<0||h>23||!Int32.TryParse(minute.Text,out m)||m<0||m>59)throw new ArgumentException("下班时间请输入有效数字：小时0–23，分钟0–59。");return h*60+m;}
 class WorkEndEditor {public TextBox Name;public CheckBox Enabled;public ComboBox Hour,Minute;}
 void AddWorkEndEditor(string name,int minute,bool enabled){
  if(endEditors.Count>=20)throw new ArgumentException("最多20个下班时段。");
  var editor=new WorkEndEditor{Name=Input(name,100),Enabled=new CheckBox{Content="启用",IsChecked=enabled,VerticalAlignment=VerticalAlignment.Center},Hour=new ComboBox{Width=88,Margin=new Thickness(4),IsEditable=true,IsTextSearchEnabled=false,MaxDropDownHeight=240},Minute=new ComboBox{Width=88,Margin=new Thickness(4),IsEditable=true,IsTextSearchEnabled=false,MaxDropDownHeight=240}};
  for(int i=0;i<24;i++)editor.Hour.Items.Add(i.ToString("D2"));for(int i=0;i<60;i++)editor.Minute.Items.Add(i.ToString("D2"));editor.Hour.SelectedIndex=minute/60;editor.Minute.SelectedIndex=minute%60;
  SetAccessibleName(editor.Name,"下班时段名称");SetAccessibleName(editor.Hour,name+"下班小时");SetAccessibleName(editor.Minute,name+"下班分钟");
  var row=new WrapPanel{Margin=new Thickness(8)};row.Children.Add(editor.Enabled);row.Children.Add(editor.Name);row.Children.Add(editor.Hour);Label(row,"时");row.Children.Add(editor.Minute);Label(row,"分");
  var card=new Border{Child=row,Background=new SolidColorBrush(Color.FromRgb(28,57,73)),CornerRadius=new CornerRadius(8),Margin=new Thickness(0,4,0,4)};
  Button(row,"删除",()=>{endEditors.Remove(editor);endSlots.Children.Remove(card);});endEditors.Add(editor);endSlots.Children.Add(card);
 }
 class ClipboardPreview {public string Value;public string Preview{get{return Value.Length>100?Value.Substring(0,100).Replace("\r", " ").Replace("\n"," ")+"…":Value.Replace("\r"," ").Replace("\n"," ");}}}
 static void Metric(Panel p,string title,TextBlock value,string unit){var column=new StackPanel();column.Children.Add(new TextBlock{Text=title,Foreground=Brushes.SlateGray});value.FontSize=34;value.FontWeight=FontWeights.SemiBold;value.Margin=new Thickness(0,7,0,1);value.Foreground=WorkbenchTheme.Ink;column.Children.Add(value);column.Children.Add(new TextBlock{Text=unit,Foreground=Brushes.SlateGray,FontSize=12});p.Children.Add(new Border{Background=new SolidColorBrush(Color.FromRgb(243,246,250)),CornerRadius=new CornerRadius(12),Padding=new Thickness(20),Width=195,Margin=new Thickness(0,0,12,0),Child=column});}
 static void SetAccessibleName(DependencyObject control,string value){System.Windows.Automation.AutomationProperties.SetName(control,value);}
 static TextBox Input(string value,double width){return new TextBox{Text=value,Width=width,Margin=new Thickness(0,4,10,4),Padding=new Thickness(4)};}
 StackPanel Page(string name){var p=new StackPanel{Margin=new Thickness(25)};p.SetValue(TextBlock.ForegroundProperty,WorkbenchTheme.Ink);p.SetValue(TextBlock.FontWeightProperty,FontWeights.Normal);WorkbenchTheme.PageHeading(p,name,"");tabs.Items.Add(new TabItem{Header=name,Content=new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto}});return p;}
 static WrapPanel Row(Panel page){var p=new WrapPanel{Margin=new Thickness(0,10,0,0)};page.Children.Add(p);return p;}
 static void Label(Panel p,string value){p.Children.Add(new TextBlock{Text=value,Margin=new Thickness(0,4,8,4),VerticalAlignment=VerticalAlignment.Center});}
 static void Description(Panel p,string value){p.Children.Add(new TextBlock{Text=value,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,14),Foreground=Brushes.DimGray});}
 static int Number(TextBox field,int max){int value;if(!Int32.TryParse(field.Text,out value))throw new ArgumentException("请输入整数分钟。");SkillEngine.Minutes(value,max);return value;}
 void Run(Action action,bool save){try{action();if(save)runtime.Save();Update();}catch(Exception e){if(!(e is ArgumentException)&&!(e is System.IO.IOException)&&!(e is UnauthorizedAccessException)&&!(e is System.Runtime.InteropServices.ExternalException)&&!(e is System.ComponentModel.Win32Exception))throw;MessageBox.Show(e.Message,"柯南技能中心",MessageBoxButton.OK,MessageBoxImage.Information);}}
 void Button(Panel p,string name,Action action){AddButton(p,name,()=>Run(action,true));}void Tool(Panel p,string name,Action action){AddButton(p,name,()=>Run(action,false));}
 static void AddButton(Panel p,string name,Action action){var b=new Button{Content=name,Padding=new Thickness(12,6,12,6),Margin=new Thickness(0,4,8,4),HorizontalAlignment=HorizontalAlignment.Left};b.Click+=(s,e)=>action();p.Children.Add(b);}
 void Transform(Func<string,string> run){if(text.Text.Length>100000)throw new ArgumentException("文本工具最多处理10万字符。");text.Text=run(text.Text);}
 static void Open(string uri){if(!DesktopActions.OpenUri(uri))throw new ArgumentException("Windows未注册此功能入口。");}
 readonly System.Collections.Generic.Dictionary<string,FrameworkElement> embedded=new System.Collections.Generic.Dictionary<string,FrameworkElement>();
 public FrameworkElement TakePage(string name){FrameworkElement element;if(embedded.TryGetValue(name,out element)){var decorator=element.Parent as Decorator;if(decorator!=null)decorator.Child=null;var owner=element.Parent as ContentControl;if(owner!=null)owner.Content=null;var panel=element.Parent as Panel;if(panel!=null)panel.Children.Remove(element);return element;}foreach(TabItem tab in tabs.Items)if(Convert.ToString(tab.Header)==name){element=(FrameworkElement)tab.Content;tab.Content=null;embedded[name]=element;return element;}throw new ArgumentException("页面不存在："+name);}
 public void ShowPage(string name){foreach(TabItem tab in tabs.Items)if(Convert.ToString(tab.Header)==name){tabs.SelectedItem=tab;break;}}
 public void SelectTask(string id){ShowPage("待办计划");var t=advanced.Engine.Data.Tasks.FirstOrDefault(x=>x.Id==id);if(t!=null&&t.Done)showDone.IsChecked=true;Update();taskList.SelectedItem=t;}
 public void SelectFile(string id){ShowPage("文件观察");fileList.SelectedItem=advanced.Engine.Data.Files.FirstOrDefault(x=>x.Id==id);}
 public void SelectReminder(string id){ShowPage("提醒");reminders.SelectedItem=Engine.Data.Reminders.FirstOrDefault(r=>r.Id==id);}
 public void Update(){
  endStatus.Text=Engine.WorkEndStatus(DateTime.UtcNow);
  var taskSelected=taskList.SelectedItem as SkillTask;taskList.ItemsSource=advanced.Engine.Data.Tasks.Where(t=>!t.Done||showDone.IsChecked==true).OrderBy(t=>t.Done).ThenByDescending(t=>t.Priority).ThenBy(t=>t.DueUtc??DateTime.MaxValue).ToArray();if(taskSelected!=null)taskList.SelectedItem=advanced.Engine.Data.Tasks.FirstOrDefault(t=>t.Id==taskSelected.Id);
  overviewTasks.Text=advanced.Engine.Data.Tasks.Count(t=>!t.Done).ToString();overviewFocus.Text=Engine.Data.Focus.TotalMinutes.ToString();overviewReminders.Text=Engine.Data.Reminders.Count(r=>r.Enabled).ToString();
  var next=Engine.Data.Reminders.Where(r=>r.Enabled).OrderBy(r=>r.DueUtc).FirstOrDefault();var today=advanced.Engine.Data.Tasks.Where(t=>!t.Done&&t.DueUtc.HasValue&&t.DueUtc.Value.ToLocalTime().Date<=DateTime.Today).OrderByDescending(t=>t.Priority).Take(3).ToArray();overviewNext.Text="接下来\n"+(next==null?"暂无等待中的提醒":next.DueUtc.ToLocalTime().ToString("HH:mm")+"  "+next.Label)+"\n\n今日待办\n"+(today.Length==0?"今天没有到期的待办，可以安排新的计划。":String.Join("\n",today.Select(t=>"○  "+t.Title).ToArray()));
  var clip=clipboardList.SelectedItem as ClipboardPreview;clipboardList.ItemsSource=advanced.Clipboard.Items.Select(v=>new ClipboardPreview{Value=v}).ToArray();if(clip!=null)clipboardList.SelectedItem=clipboardList.Items.Cast<ClipboardPreview>().FirstOrDefault(i=>i.Value==clip.Value);
  var file=fileList.SelectedItem as FileWatchSetting;fileList.ItemsSource=advanced.Engine.Data.Files.ToArray();if(file!=null)fileList.SelectedItem=advanced.Engine.Data.Files.FirstOrDefault(x=>x.Id==file.Id);hotkeyState.Text=advanced.HotkeyStatus;
  var f=Engine.Data.Focus;string mode=f.Mode=="work"?"专注":f.Mode=="long"?"长休":"短休";double left=f.Running||f.Paused?Engine.FocusRemaining(DateTime.UtcNow):f.WorkMinutes*60.0;
  focus.Text=(f.Paused?"已暂停 · ":f.Running?mode+" · ":"准备开始 · ")+SkillLogic.Clock(left);stats.Text="今天已完成 "+f.Completed+" 轮专注 · "+f.TotalMinutes+" 分钟";
  double total=(f.Mode=="work"?f.WorkMinutes:f.Mode=="long"?f.LongMinutes:f.ShortMinutes)*60.0;progress.Value=f.Running||f.Paused?Math.Max(0,Math.Min(100,100*(1-left/Math.Max(1,total)))):0;
  var selected=reminders.SelectedItem as SkillReminder;reminders.ItemsSource=Engine.Data.Reminders.OrderBy(r=>!r.Enabled).ThenBy(r=>r.DueUtc).ToArray();if(selected!=null)reminders.SelectedItem=Engine.Data.Reminders.FirstOrDefault(r=>r.Id==selected.Id);
  selecting=true;notes.ItemsSource=Engine.Data.Notes.OrderByDescending(n=>n.UpdatedUtc).ToArray();if(editingNote!=null)notes.SelectedItem=Engine.Data.Notes.FirstOrDefault(n=>n.Id==editingNote);selecting=false;
 }
